/**
 * UrbanVerse Standalone ReactDOM Runtime
 * Zero-dependency DOM renderer for React
 */
(function(global) {
  'use strict';

  const React = global.React;
  if (!React) {
    throw new Error('React must be loaded before ReactDOM');
  }

  const SVG_NS = 'http://www.w3.org/2000/svg';
  const SVG_TAGS = new Set([
    'svg', 'g', 'path', 'polygon', 'polyline', 'rect', 'circle', 'ellipse',
    'line', 'text', 'tspan', 'defs', 'linearGradient', 'radialGradient', 'stop'
  ]);

  function isEventProp(key) {
    return key.startsWith('on');
  }

  function setAttribute(dom, key, value, prevValue, isSvg) {
    if (key === 'children' || key === 'key') return;

    if (isEventProp(key)) {
      const eventName = key.toLowerCase().substring(2);
      if (prevValue) dom.removeEventListener(eventName, prevValue);
      if (value) dom.addEventListener(eventName, value);
      return;
    }

    if (key === 'style') {
      if (typeof value === 'object' && value !== null) {
        Object.assign(dom.style, value);
      } else {
        dom.style.cssText = value || '';
      }
      return;
    }

    if (key === 'className') {
      if (isSvg) {
        dom.setAttribute('class', value || '');
      } else {
        dom.className = value || '';
      }
      return;
    }

    if (key === 'value' || key === 'checked') {
      dom[key] = value;
      return;
    }

    if (value === null || value === undefined || value === false) {
      dom.removeAttribute(key);
    } else {
      dom.setAttribute(key, value === true ? '' : value);
    }
  }

  class ComponentInstance {
    constructor(vnode, container, parentInstance) {
      this.vnode = vnode;
      this.container = container;
      this.parentInstance = parentInstance;
      this.dom = null;
      this.childInstance = null;
      this.hooks = [];
      this.effects = [];
      this.scheduled = false;
    }

    render() {
      React._internals.currentComponent = this;
      React._internals.hookIndex = 0;
      this.effects = [];

      let renderedVNode;
      try {
        renderedVNode = this.vnode.type(this.vnode.props);
      } finally {
        React._internals.currentComponent = null;
      }

      this.childInstance = reconcile(this.container, this.childInstance, renderedVNode, this);
      this.dom = this.childInstance.dom;

      // Run effects asynchronously
      queueMicrotask(() => {
        for (const eff of this.effects) {
          if (eff.cleanup) {
            try { eff.cleanup(); } catch (e) { console.error('Effect cleanup error:', e); }
          }
          try {
            const cleanup = eff.effect();
            this.hooks[eff.index] = { deps: eff.deps, cleanup: typeof cleanup === 'function' ? cleanup : null };
          } catch (e) {
            console.error('Effect execution error:', e);
          }
        }
      });

      return this;
    }

    scheduleUpdate() {
      if (this.scheduled) return;
      this.scheduled = true;
      queueMicrotask(() => {
        this.scheduled = false;
        this.render();
      });
    }

    destroy() {
      for (const hook of this.hooks) {
        if (hook && typeof hook.cleanup === 'function') {
          try { hook.cleanup(); } catch (e) {}
        }
      }
      if (this.childInstance) {
        this.childInstance.destroy();
      }
    }
  }

  function instantiate(vnode, container, parentInstance) {
    if (!vnode) return null;

    const isFunctionComponent = typeof vnode.type === 'function';

    if (isFunctionComponent) {
      const instance = new ComponentInstance(vnode, container, parentInstance);
      return instance.render();
    }

    const isText = vnode.type === 'TEXT_ELEMENT';
    const isSvg = (parentInstance && parentInstance.isSvg) || SVG_TAGS.has(vnode.type);
    const dom = isText
      ? document.createTextNode(vnode.props.nodeValue)
      : isSvg
        ? document.createElementNS(SVG_NS, vnode.type)
        : document.createElement(vnode.type);

    const childInstances = [];
    if (!isText && vnode.props) {
      for (const [key, value] of Object.entries(vnode.props)) {
        setAttribute(dom, key, value, null, isSvg);
      }

      const children = vnode.props.children || [];
      for (const child of children) {
        const childInst = instantiate(child, dom, { isSvg, dom });
        if (childInst) {
          childInstances.push(childInst);
          dom.appendChild(childInst.dom);
        }
      }
    }

    return {
      vnode,
      dom,
      childInstances,
      isSvg,
      destroy() {
        for (const c of childInstances) if (c && c.destroy) c.destroy();
      }
    };
  }

  function reconcile(container, prevInstance, nextVNode, parentInstance) {
    if (!prevInstance) {
      const newInstance = instantiate(nextVNode, container, parentInstance);
      if (newInstance && newInstance.dom && newInstance.dom.parentNode !== container) {
        container.appendChild(newInstance.dom);
      }
      return newInstance;
    }

    if (!nextVNode) {
      if (prevInstance.dom && prevInstance.dom.parentNode) {
        prevInstance.dom.parentNode.removeChild(prevInstance.dom);
      }
      prevInstance.destroy();
      return null;
    }

    // Function component reconciliation
    if (prevInstance instanceof ComponentInstance) {
      if (prevInstance.vnode.type === nextVNode.type) {
        prevInstance.vnode = nextVNode;
        return prevInstance.render();
      } else {
        const newInstance = instantiate(nextVNode, container, parentInstance);
        if (prevInstance.dom && prevInstance.dom.parentNode) {
          prevInstance.dom.parentNode.replaceChild(newInstance.dom, prevInstance.dom);
        }
        prevInstance.destroy();
        return newInstance;
      }
    }

    // Tag mismatch
    if (prevInstance.vnode.type !== nextVNode.type) {
      const newInstance = instantiate(nextVNode, container, parentInstance);
      if (prevInstance.dom && prevInstance.dom.parentNode) {
        prevInstance.dom.parentNode.replaceChild(newInstance.dom, prevInstance.dom);
      }
      prevInstance.destroy();
      return newInstance;
    }

    // Text node update
    if (nextVNode.type === 'TEXT_ELEMENT') {
      if (prevInstance.vnode.props.nodeValue !== nextVNode.props.nodeValue) {
        prevInstance.dom.nodeValue = nextVNode.props.nodeValue;
        prevInstance.vnode = nextVNode;
      }
      return prevInstance;
    }

    // DOM node update
    const dom = prevInstance.dom;
    const isSvg = prevInstance.isSvg;
    const prevProps = prevInstance.vnode.props || {};
    const nextProps = nextVNode.props || {};

    // Remove old props
    for (const key of Object.keys(prevProps)) {
      if (key !== 'children' && !(key in nextProps)) {
        setAttribute(dom, key, null, prevProps[key], isSvg);
      }
    }

    // Set new / updated props
    for (const [key, value] of Object.entries(nextProps)) {
      if (key !== 'children' && prevProps[key] !== value) {
        setAttribute(dom, key, value, prevProps[key], isSvg);
      }
    }

    // Reconcile children
    const prevChildren = prevInstance.childInstances || [];
    const nextChildren = nextProps.children || [];
    const newChildInstances = [];
    const maxLength = Math.max(prevChildren.length, nextChildren.length);

    for (let i = 0; i < maxLength; i++) {
      const p = prevChildren[i];
      const n = nextChildren[i];
      const child = reconcile(dom, p, n, { isSvg, dom });
      if (child) newChildInstances.push(child);
    }

    prevInstance.vnode = nextVNode;
    prevInstance.childInstances = newChildInstances;
    return prevInstance;
  }

  function createRoot(container) {
    let currentInstance = null;
    return {
      render(vnode) {
        currentInstance = reconcile(container, currentInstance, vnode, null);
      },
      unmount() {
        if (currentInstance) {
          if (currentInstance.dom && currentInstance.dom.parentNode) {
            currentInstance.dom.parentNode.removeChild(currentInstance.dom);
          }
          currentInstance.destroy();
          currentInstance = null;
        }
      }
    };
  }

  const ReactDOM = {
    createRoot,
    render(vnode, container) {
      const root = createRoot(container);
      root.render(vnode);
      return root;
    },
    version: '18.3.1'
  };

  global.ReactDOM = ReactDOM;
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = ReactDOM;
  }
})(typeof window !== 'undefined' ? window : globalThis);
